import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { DashboardService } from '../../services/dashboard.service';
import { ExportService } from '../../services/export.service';
import { AuthService } from '../../core/services/auth.service';
import { TransacaoService, Transacao } from '../../services/transacao.service';
import { CategoriaService, Categoria } from '../../services/categoria.service';
import { forkJoin } from 'rxjs';
import { TranslationPipe } from '../../core/i18n/translation.pipe';
import { I18nService } from '../../core/i18n/i18n.service';

interface DashboardResumo {
  saldo_atual: number;
  receitas: number;
  despesas: number;
  total_transacoes?: number;
}

interface Cotacoes {
  USD_BRL?: { cotacao: number; baixa?: number; alta?: number };
  EUR_BRL?: { cotacao: number; baixa?: number; alta?: number };
  AOA_BRL?: { cotacao: number; baixa?: number; alta?: number };
  AOA_USD?: { cotacao: number; baixa?: number; alta?: number };
  AOA_EUR?: { cotacao: number; baixa?: number; alta?: number };
}

interface DashboardResponse {
  success: boolean;
  resumo: DashboardResumo;
  cotacoes_atuais: Cotacoes | null;
  data_atualizacao: string;
}

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, RouterLink, TranslationPipe],
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.scss']
})
export class DashboardComponent implements OnInit {
  isLoading = true;
  hasError = false;
  errorMessage = '';
  isExporting = false;

  resumo: DashboardResumo | null = null;
  cotacoes: Cotacoes | null = null;
  dataAtualizacao: string | null = null;
  nomeUtilizador = '';
  transacoesRecentes: Transacao[] = [];
  categoriasMap: Record<number, string> = {};

  saldoEmUSD = 0;
  saldoEmEUR = 0;
  receitasEmUSD = 0;
  despesasEmUSD = 0;

  constructor(
    private dashboardService: DashboardService,
    private exportService: ExportService,
    private authService: AuthService,
    private transacaoService: TransacaoService,
    private categoriaService: CategoriaService,
    private i18nService: I18nService
  ) { }

  ngOnInit(): void {
    this.nomeUtilizador = this.authService.getUserData()?.nome || this.i18nService.translate('dashboard.unknownUser');
    this.carregarDados();
  }

  private carregarDados(): void {
    this.isLoading = true;
    this.hasError = false;

    forkJoin({
      dashboard: this.dashboardService.getResumoFinanceiro(),
      transacoes: this.transacaoService.listar(),
      categorias: this.categoriaService.listar()
    }).subscribe({
      next: ({ dashboard, transacoes, categorias }) => {
        const dashboardData = dashboard as DashboardResponse;

        this.resumo = dashboardData?.resumo ?? {
          saldo_atual: 0,
          receitas: 0,
          despesas: 0,
          total_transacoes: 0
        };

        this.cotacoes = dashboardData?.cotacoes_atuais ?? {};
        this.dataAtualizacao = dashboardData?.data_atualizacao
          ? new Date(dashboardData.data_atualizacao).toLocaleString('pt-BR')
          : new Date().toLocaleString('pt-BR');

        const categoriasData = Array.isArray(categorias.data) ? (categorias.data as Categoria[]) : [];
        this.categoriasMap = categoriasData.reduce<Record<number, string>>((acc, categoria) => {
          if (categoria.id) {
            acc[categoria.id] = categoria.nome;
          }
          return acc;
        }, {});

        const transacoesData = Array.isArray(transacoes.data) ? (transacoes.data as Transacao[]) : [];
        this.transacoesRecentes = transacoesData.slice(0, 5);

        this.calcularConversoes();
        this.isLoading = false;
      },
      error: (error: any) => {
        console.error('Erro ao carregar dashboard:', error);
        this.hasError = true;
        this.errorMessage = this.i18nService.translate('dashboard.loadError');
        this.resumo = {
          saldo_atual: 0,
          receitas: 0,
          despesas: 0,
          total_transacoes: 0
        };
        this.transacoesRecentes = [];
        this.calcularConversoes();
        this.isLoading = false;
      }
    });
  }

  private calcularConversoes(): void {
    if (!this.resumo || !this.cotacoes) return;

    const cotacaoAoaUsd = this.cotacoes.AOA_USD?.cotacao || 0;
    const cotacaoAoaEur = this.cotacoes.AOA_EUR?.cotacao || 0;
    const cotacaoAoaBrl = this.cotacoes.AOA_BRL?.cotacao || 0;
    const cotacaoUsdBrl = this.cotacoes.USD_BRL?.cotacao || 0;
    const cotacaoEurBrl = this.cotacoes.EUR_BRL?.cotacao || 0;

    if (cotacaoAoaUsd > 0) {
      this.saldoEmUSD = this.resumo.saldo_atual * cotacaoAoaUsd;
      this.receitasEmUSD = this.resumo.receitas * cotacaoAoaUsd;
      this.despesasEmUSD = this.resumo.despesas * cotacaoAoaUsd;
    } else if (cotacaoAoaBrl > 0 && cotacaoUsdBrl > 0) {
      const taxaAoaUsd = cotacaoAoaBrl / cotacaoUsdBrl;
      this.saldoEmUSD = this.resumo.saldo_atual * taxaAoaUsd;
      this.receitasEmUSD = this.resumo.receitas * taxaAoaUsd;
      this.despesasEmUSD = this.resumo.despesas * taxaAoaUsd;
    }

    if (cotacaoAoaEur > 0) {
      this.saldoEmEUR = this.resumo.saldo_atual * cotacaoAoaEur;
    } else if (cotacaoAoaBrl > 0 && cotacaoEurBrl > 0) {
      const taxaAoaEur = cotacaoAoaBrl / cotacaoEurBrl;
      this.saldoEmEUR = this.resumo.saldo_atual * taxaAoaEur;
    }
  }

  recarregar(): void {
    this.carregarDados();
  }

  exportarCsv(): void {
    this.isExporting = true;
    this.hasError = false;

    try {
      this.exportService.exportarCsv('relatorio_financeiro.csv');
      this.isExporting = false;
    } catch (error: any) {
      console.error('Erro ao exportar:', error);
      this.hasError = true;
      this.errorMessage = error.message || this.i18nService.translate('dashboard.exportError');
      this.isExporting = false;
    }
  }

  formatarMoeda(valor: number, moeda: string = 'AOA'): string {
    const locale = moeda === 'AOA' ? 'pt-AO' : 'pt-BR';
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency: moeda,
      currencyDisplay: moeda === 'AOA' ? 'narrowSymbol' : 'symbol'
    }).format(valor);
  }

  formatarData(data: string): string {
    const date = new Date(`${data}T00:00:00`);
    return new Intl.DateTimeFormat('pt-BR').format(date);
  }

  obterNomeCategoria(categoriaId: number): string {
    return this.categoriasMap[categoriaId] || this.i18nService.translate('dashboard.uncategorized');
  }
}
<div class="dashboard-container">
  <div class="dashboard-shell">
    <section class="dashboard-intro">
      <h2>{{ 'dashboard.title' | t }}</h2>
      <p>{{ 'dashboard.welcome' | t }}, <strong>{{ nomeUtilizador }}</strong>. {{ 'dashboard.quickView' | t }}</p>
    </section>

    <div *ngIf="isLoading" class="loading-state">
      <div class="spinner"></div>
      <p>{{ 'dashboard.loading' | t }}</p>
    </div>

    <div *ngIf="hasError && !isLoading" class="error-state">
      <div class="error-icon">{{ 'dashboard.loadErrorTitle' | t }}</div>
      <h3>{{ 'dashboard.loadErrorTitle' | t }}</h3>
      <p>{{ errorMessage }}</p>
      <button class="btn-retry" (click)="recarregar()">{{ 'dashboard.retry' | t }}</button>
    </div>

    <div *ngIf="!isLoading && !hasError && resumo" class="dashboard-content">
      <section class="summary-grid">
        <article class="summary-card card-saldo">
          <header>
            <span>{{ 'dashboard.balanceAvailable' | t }}</span>
            <small>{{ dataAtualizacao }}</small>
          </header>
          <div class="saldo-value">{{ formatarMoeda(resumo.saldo_atual) }}</div>
          <footer>
            <span *ngIf="resumo.saldo_atual >= 0">{{ 'dashboard.positiveStatus' | t }}</span>
            <span *ngIf="resumo.saldo_atual < 0">{{ 'dashboard.negativeStatus' | t }}</span>
          </footer>
        </article>

        <article class="summary-card card-receitas">
          <header>
            <span>{{ 'dashboard.totalIncome' | t }}</span>
            <strong>{{ 'dashboard.income' | t }}</strong>
          </header>
          <div class="money positive">{{ formatarMoeda(resumo.receitas) }}</div>
          <p>{{ 'dashboard.periodIncome' | t }}</p>
        </article>

        <article class="summary-card card-despesas">
          <header>
            <span>{{ 'dashboard.totalExpense' | t }}</span>
            <strong>{{ 'dashboard.expense' | t }}</strong>
          </header>
          <div class="money negative">{{ formatarMoeda(resumo.despesas) }}</div>
          <p>{{ 'dashboard.periodExpense' | t }}</p>
        </article>
      </section>

      <section class="widget-grid">
        <article class="widget-card cambio" *ngIf="cotacoes">
          <div class="widget-head">
            <h3>{{ 'dashboard.exchangePanel' | t }}</h3>
            <span>{{ 'dashboard.convertedBalance' | t }}</span>
          </div>

          <div class="cambio-list" *ngIf="cotacoes.AOA_USD || cotacoes.AOA_EUR || cotacoes.USD_BRL || cotacoes.EUR_BRL; else semCotacao">
            <div *ngIf="cotacoes.AOA_USD || cotacoes.USD_BRL" class="cambio-item">
              <span>{{ 'dashboard.balanceUsd' | t }}</span>
              <strong>{{ formatarMoeda(saldoEmUSD, 'USD') }}</strong>
            </div>
            <div *ngIf="cotacoes.AOA_EUR || cotacoes.EUR_BRL" class="cambio-item">
              <span>{{ 'dashboard.balanceEur' | t }}</span>
              <strong>{{ formatarMoeda(saldoEmEUR, 'EUR') }}</strong>
            </div>
          </div>

          <ng-template #semCotacao>
            <div class="recent-empty">
              <p>{{ 'dashboard.ratesUnavailable' | t }}</p>
            </div>
          </ng-template>
        </article>

        <article class="widget-card actions">
          <div class="widget-head">
            <h3>{{ 'dashboard.quickActions' | t }}</h3>
            <span>{{ 'dashboard.productivity' | t }}</span>
          </div>
          <div class="actions-row">
            <button class="action-btn primary" (click)="exportarCsv()" [disabled]="isExporting">
              <span *ngIf="!isExporting">{{ 'common.exportCsv' | t }}</span>
              <span *ngIf="isExporting">{{ 'dashboard.exporting' | t }}</span>
            </button>
            <button class="action-btn" (click)="recarregar()">{{ 'dashboard.refreshData' | t }}</button>
            <a routerLink="/transacoes" class="action-btn ghost">{{ 'dashboard.viewTransactions' | t }}</a>
          </div>
        </article>
      </section>

      <section class="recent-section">
        <div class="recent-head">
          <h3>{{ 'dashboard.latestTransactions' | t }}</h3>
          <a routerLink="/transacoes">{{ 'dashboard.viewAll' | t }}</a>
        </div>

        <div class="recent-list" *ngIf="transacoesRecentes.length > 0; else emptyRecent">
          <article class="recent-item" *ngFor="let item of transacoesRecentes">
            <div class="recent-icon">TX</div>
            <div class="recent-info">
              <strong>{{ item.descricao }}</strong>
              <span>{{ formatarData(item.data) }} - {{ obterNomeCategoria(item.categoria_id) }}</span>
            </div>
            <div class="recent-value" [class.positive]="item.tipo === 'receita'" [class.negative]="item.tipo === 'despesa'">
              {{ item.tipo === 'receita' ? '+' : '-' }} {{ formatarMoeda(item.valor) }}
            </div>
          </article>
        </div>

        <ng-template #emptyRecent>
          <div class="recent-empty">
            <p>{{ 'dashboard.noMovements' | t }}</p>
            <a routerLink="/transacoes">{{ 'dashboard.addTransaction' | t }}</a>
          </div>
        </ng-template>
      </section>
    </div>
  </div>
</div>
